def list_datasets(limit=None, offset=None, tasks=None, modalities=None, languages=None, license=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0042000" if __import__("os").path.isdir("./environment_mix/0042000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _extract_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    t0 = time.time()
    status = "ok"
    # --- validate pagination ---
    if offset is None:
        offset = 0
    if not isinstance(offset, int):
        status = "error"
        resp = _err("VALIDATION_ERROR", "offset must be an integer", field="offset")
    elif offset < 0:
        status = "error"
        resp = _err("VALIDATION_ERROR", "offset must be >= 0", field="offset")
    else:
        if limit is None:
            limit_val = 20
        else:
            limit_val = limit
        if not isinstance(limit_val, int):
            status = "error"
            resp = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        elif limit_val <= 0:
            status = "error"
            resp = _err("VALIDATION_ERROR", "limit must be > 0", field="limit")
        else:
            # --- validate filters types ---
            def _validate_str_list(v, field):
                if v is None:
                    return None, None
                if not isinstance(v, list):
                    return None, _err("VALIDATION_ERROR", f"{field} must be an array of strings", field=field)
                for i, it in enumerate(v):
                    if not isinstance(it, str) or not it.strip():
                        return None, _err("VALIDATION_ERROR", f"{field} must contain only non-empty strings", field=field, index=i)
                return [s.strip() for s in v], None

            tasks_v, e = _validate_str_list(tasks, "tasks")
            if e:
                status = "error"
                resp = e
            else:
                modalities_v, e = _validate_str_list(modalities, "modalities")
                if e:
                    status = "error"
                    resp = e
                else:
                    languages_v, e = _validate_str_list(languages, "languages")
                    if e:
                        status = "error"
                        resp = e
                    else:
                        if license is not None and (not isinstance(license, str) or not license.strip()):
                            status = "error"
                            resp = _err("VALIDATION_ERROR", "license must be a non-empty string", field="license")
                        else:
                            license_v = license.strip() if isinstance(license, str) else None

                            # --- load data ---
                            raw = _load("datasets.json")
                            rows = _extract_rows(raw)

                            # Build known values to validate "unrecognized/can't match" filter values
                            known_tasks = set()
                            known_modalities = set()
                            known_languages = set()
                            known_licenses = set()
                            for d in rows:
                                for t in d.get("tasks", []) if isinstance(d.get("tasks", []), list) else []:
                                    if isinstance(t, str):
                                        known_tasks.add(t)
                                for m in d.get("modalities", []) if isinstance(d.get("modalities", []), list) else []:
                                    if isinstance(m, str):
                                        known_modalities.add(m)
                                for l in d.get("languages", []) if isinstance(d.get("languages", []), list) else []:
                                    if isinstance(l, str):
                                        known_languages.add(l)
                                lic = d.get("license")
                                if isinstance(lic, str):
                                    known_licenses.add(lic)

                            # Reject filters referencing unrecognized values
                            if tasks_v:
                                bad = [t for t in tasks_v if t not in known_tasks]
                                if bad:
                                    status = "error"
                                    resp = _err("VALIDATION_ERROR", "Unrecognized tasks filter value(s)", field="tasks", values=bad)
                            if status == "ok" and modalities_v:
                                bad = [m for m in modalities_v if m not in known_modalities]
                                if bad:
                                    status = "error"
                                    resp = _err("VALIDATION_ERROR", "Unrecognized modalities filter value(s)", field="modalities", values=bad)
                            if status == "ok" and languages_v:
                                # validate language codes shape too (simple BCP-47-ish)
                                bad_shape = [l for l in languages_v if not re.fullmatch(r"[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*", l)]
                                if bad_shape:
                                    status = "error"
                                    resp = _err("VALIDATION_ERROR", "Invalid language code(s)", field="languages", values=bad_shape)
                                else:
                                    bad = [l for l in languages_v if l not in known_languages]
                                    if bad:
                                        status = "error"
                                        resp = _err("VALIDATION_ERROR", "Unrecognized languages filter value(s)", field="languages", values=bad)
                            if status == "ok" and license_v:
                                if license_v not in known_licenses:
                                    status = "error"
                                    resp = _err("VALIDATION_ERROR", "Unrecognized license filter value", field="license", value=license_v)

                            if status == "ok":
                                # --- apply filters ---
                                filtered = rows
                                if tasks_v:
                                    filtered = [d for d in filtered if isinstance(d, dict) and any(t in (d.get("tasks") or []) for t in tasks_v)]
                                if modalities_v:
                                    filtered = [d for d in filtered if isinstance(d, dict) and any(m in (d.get("modalities") or []) for m in modalities_v)]
                                if languages_v:
                                    filtered = [d for d in filtered if isinstance(d, dict) and any(l in (d.get("languages") or []) for l in languages_v)]
                                if license_v:
                                    filtered = [d for d in filtered if isinstance(d, dict) and d.get("license") == license_v]

                                # stable sort by id
                                filtered.sort(key=lambda x: (x.get("id") if isinstance(x, dict) else ""))

                                total = len(filtered)
                                page = filtered[offset: offset + limit_val]
                                has_more = (offset + limit_val) < total
                                resp = {
                                    "data": page,
                                    "meta": {
                                        "total": total,
                                        "limit": limit_val,
                                        "offset": offset,
                                        "has_more": has_more,
                                        "next_offset": (offset + limit_val) if has_more else None,
                                    },
                                }

    # observable dynamics: try to write request log if collection exists
    latency_ms = int((time.time() - t0) * 1000)
    try:
        for fname in ("request_logs.json", "usage.json", "audit.json"):
            p = os.path.join(_DB, fname)
            if os.path.exists(p):
                obj = _load(fname)
                if isinstance(obj, dict):
                    logs = obj.get("rows")
                    if not isinstance(logs, list):
                        logs = []
                    logs.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "list_datasets",
                        "timestamp": _now(),
                        "status": status,
                        "latency_ms": latency_ms,
                    })
                    obj["rows"] = logs
                    _save(fname, obj)
                elif isinstance(obj, list):
                    obj.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "list_datasets",
                        "timestamp": _now(),
                        "status": status,
                        "latency_ms": latency_ms,
                    })
                    _save(fname, obj)
                break
    except Exception:
        pass

    return resp

