    if query is None or not isinstance(query, str) or not query.strip():
        status = "error"
        resp = _err("VALIDATION_ERROR", "query is required and must be a non-empty string", field="query")
    else:
        if offset is None:
            offset = 0
        if not isinstance(offset, int):
            status = "error"
            resp = _err("VALIDATION_ERROR", "offset must be an integer", field="offset")
        elif offset < 0:
            status = "error"
            resp = _err("VALIDATION_ERROR", "offset must be >= 0", field="offset")
        else:
            if limit is None:
                limit_val = 20
            else:
                limit_val = limit
            if not isinstance(limit_val, int):
                status = "error"
                resp = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
            elif limit_val <= 0:
                status = "error"
                resp = _err("VALIDATION_ERROR", "limit must be > 0", field="limit")
            else:
                if category is not None and (not isinstance(category, str) or not category.strip()):
                    status = "error"
                    resp = _err("VALIDATION_ERROR", "category must be a non-empty string", field="category")
                else:
                    q = query.strip()
                    cat_v = category.strip() if isinstance(category, str) else None

                    rows = _extract_rows(_load("papers.json"))
                    known_categories = set()
                    for p in rows:
                        if isinstance(p, dict) and isinstance(p.get("category"), str):
                            known_categories.add(p["category"])

                    if cat_v and cat_v not in known_categories:
                        status = "error"
                        resp = _err("VALIDATION_ERROR", "Unrecognized category filter value", field="category", value=cat_v)
                    else:
                        # case-insensitive word-ish search: all terms must match somewhere
                        terms = [t for t in re.split(r"\s+", q.lower()) if t]
                        def _match(p):
                            title = (p.get("title") or "")
                            summ = (p.get("summary") or "")
                            hay = (str(title) + " " + str(summ)).lower()
                            return all(t in hay for t in terms)

                        filtered = [p for p in rows if isinstance(p, dict) and _match(p)]
                        if cat_v:
                            filtered = [p for p in filtered if p.get("category") == cat_v]

                        filtered.sort(key=lambda x: (x.get("title") if isinstance(x, dict) else ""))
                        total = len(filtered)
                        page = filtered[offset: offset + limit_val]
                        has_more = (offset + limit_val) < total
                        resp = {
                            "data": page,
                            "meta": {
                                "total": total,
                                "limit": limit_val,
                                "offset": offset,
                                "has_more": has_more,
                                "next_offset": (offset + limit_val) if has_more else None,
                                "query": q,
                            },
                        }

    latency_ms = int((time.time() - t0) * 1000)
    try:
        for fname in ("request_logs.json", "usage.json", "audit.json"):
            p = os.path.join(_DB, fname)
            if os.path.exists(p):
                obj = _load(fname)
                if isinstance(obj, dict):
                    logs = obj.get("rows")
                    if not isinstance(logs, list):
                        logs = []
                    logs.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "search_papers",
                        "timestamp": _now(),
                        "status": status,
                        "latency_ms": latency_ms,
                    })
                    obj["rows"] = logs
                    _save(fname, obj)
                elif isinstance(obj, list):
                    obj.append({
                        "id": f"req_{int(time.time()*1000)}",
                        "endpoint": "search_papers",
                        "timestamp": _now(),
                        "status": status,
                        "latency_ms": latency_ms,
                    })
                    _save(fname, obj)
                break
    except Exception:
        pass

    return resp
